export const palettes: Record<PaperTheme, Record<ColorScaleName, Record<ScaleStep, string>>> = {
  light: {
    neutral: scale(lightNeutral),
    accent: scale(lightAccent),
    success: scale(lightSuccess),
    warning: scale(lightWarning),
    danger: scale(lightDanger),
    info: scale(lightInfo)
  },
  dark: {
    neutral: scale(darkNeutral),
    accent: scale(darkAccent),
    success: scale(darkSuccess),
    warning: scale(darkWarning),
    danger: scale(darkDanger),
    info: scale(darkInfo)
  },
  hc: {
    neutral: scale(hcNeutral),
    accent: scale(hcAccent),
    success: scale(hcSuccess),
    warning: scale(hcWarning),
    danger: scale(hcDanger),
    info: scale(hcInfo)
  }
};

/** Status mapped onto the semantic scales so one language is used everywhere. */
export const statusAlias: Record<StatusName, { scale: ColorScaleName; step: ScaleStep }> = {
  idle: { scale: 'neutral', step: 8 },
  thinking: { scale: 'info', step: 9 },
  working: { scale: 'warning', step: 9 },
  waiting: { scale: 'accent', step: 9 },
  blocked: { scale: 'danger', step: 9 },
  success: { scale: 'success', step: 9 },
  ghost: { scale: 'neutral', step: 6 },
  compacting: { scale: 'accent', step: 8 },
  looping: { scale: 'warning', step: 10 },
  typing: { scale: 'warning', step: 8 }
};

