export const focusRing = {
  light: '0 0 0 2px var(--paper-neutral-1), 0 0 0 4px var(--paper-accent-9)',
  dark: '0 0 0 2px var(--paper-neutral-1), 0 0 0 4px var(--paper-accent-9)',
  hc: '0 0 0 3px var(--paper-neutral-1), 0 0 0 6px var(--paper-accent-9)'
} as const;

function themeBlock(theme: PaperTheme, selector: string): string {
  const p = palettes[theme];
  const elev = elevation[theme];
  const lines: string[] = [`${selector} {`];
  for (const name of COLOR_SCALES) {
    for (const step of SCALE_STEPS) {
      lines.push(`  --paper-${name}-${step}: ${p[name][step]};`);
    }
  }
  for (const status of STATUS_NAMES) {
    const a = statusAlias[status];
    lines.push(`  --paper-status-${status}: var(--paper-${a.scale}-${a.step});`);
  }
  lines.push(`  --paper-elev-1: ${elev[1]};`);
  lines.push(`  --paper-elev-2: ${elev[2]};`);
  lines.push(`  --paper-elev-3: ${elev[3]};`);
  lines.push(`  --paper-focus-ring: ${focusRing[theme]};`);
  lines.push(`  --paper-bg: var(--paper-neutral-1);`);
  lines.push(`  --paper-bg-subtle: var(--paper-neutral-2);`);
  lines.push(`  --paper-surface: var(--paper-neutral-2);`);
  lines.push(`  --paper-surface-hover: var(--paper-neutral-3);`);
  lines.push(`  --paper-border: var(--paper-neutral-6);`);
  lines.push(`  --paper-border-strong: var(--paper-neutral-7);`);
  lines.push(`  --paper-text: var(--paper-neutral-12);`);
  lines.push(`  --paper-text-muted: var(--paper-neutral-11);`);
  lines.push(`  color: var(--paper-text);`);
  lines.push(`  background: var(--paper-bg);`);
  lines.push('}');
  return lines.join('\n');
}

function sharedBlock(): string {
  const lines: string[] = [':root {'];
  for (const [k, v] of Object.entries(space)) {
    lines.push(`  --paper-space-${k}: ${v}px;`);
  }
  lines.push(`  --paper-radius-sm: ${radius.sm}px;`);
  lines.push(`  --paper-radius-md: ${radius.md}px;`);
  lines.push(`  --paper-radius-lg: ${radius.lg}px;`);
  lines.push(`  --paper-radius-xl: ${radius.xl}px;`);
  lines.push(`  --paper-radius-full: ${radius.full}px;`);
  lines.push(`  --paper-font-ui: ${type.ui};`);
  lines.push(`  --paper-font-mono: ${type.mono};`);
  for (const [k, v] of Object.entries(type.size)) {
    lines.push(`  --paper-text-${k}: ${v}px;`);
  }
  for (const [k, v] of Object.entries(type.line)) {
    lines.push(`  --paper-leading-${k}: ${v}px;`);
  }
  lines.push(`  --paper-weight-regular: ${type.weight.regular};`);
  lines.push(`  --paper-weight-medium: ${type.weight.medium};`);
  lines.push(`  --paper-weight-semibold: ${type.weight.semibold};`);
  lines.push(`  --paper-duration-fast: ${motion.fast}ms;`);
  lines.push(`  --paper-duration-base: ${motion.base}ms;`);
  lines.push(`  --paper-duration-slow: ${motion.slow}ms;`);
  lines.push(`  --paper-ease: ${motion.ease};`);
  lines.push('}');
  lines.push('');
  lines.push('@media (prefers-reduced-motion: reduce) {');
  lines.push('  :root {');
  lines.push('    --paper-duration-fast: 0.01ms;');
  lines.push('    --paper-duration-base: 0.01ms;');
  lines.push('    --paper-duration-slow: 0.01ms;');
  lines.push('  }');
  lines.push('}');
  return lines.join('\n');
}

export function emitPaperCss(): string {
  return [
    '/* Generated from src/renderer/src/design/paper/tokens.ts — do not edit by hand. */',
    '/* Prefix --paper-* so this never collides with classic --cth-* tokens. */',
    sharedBlock(),
    '',
    themeBlock('light', ':root, :root[data-paper-theme="light"]'),
    '',
    themeBlock('dark', ':root[data-paper-theme="dark"]'),
    '',
    themeBlock('hc', ':root[data-paper-theme="hc"]'),
    '',
    'html[data-paper-theme] {',
    '  font-family: var(--paper-font-ui);',
    '  font-size: var(--paper-text-md);',
    '  line-height: var(--paper-leading-md);',
    '  font-feature-settings: "cv11", "ss01", "tnum";',
    '  -webkit-font-smoothing: antialiased;',
    '  text-rendering: optimizeLegibility;',
    '}',
    '',
    'html[data-paper-theme] :focus-visible {',
    '  outline: none;',
    '  box-shadow: var(--paper-focus-ring);',
    '}',
    ''
  ].join('\n');
}

const THEME_ATTR = 'paperTheme';

export function applyPaperTheme(theme: PaperTheme, root: HTMLElement = document.documentElement): void {
  root.dataset[THEME_ATTR] = theme;
}

export function paperThemeFromRoot(root: HTMLElement = document.documentElement): PaperTheme {
  const v = root.dataset[THEME_ATTR];
  if (v === 'dark' || v === 'hc' || v === 'light') return v;
  return 'light';
}
